    function loadLabels() {
        model_name = parentNode.label
        // [v]:Entity Node Id ; [vt]: Knowledge Graph Id
        let data_graphs = {}
        nodes.forEach(node => {
            if (node.name !== undefined) {
                if (node.props) {
                    node.props.forEach(prop => {
                        if (prop.p === "input") {
                            // check if the knowledge graph type exists in the current graph labels; 
                            if (!data_graphs[prop.vt]) {
                                let type_init = { [prop.v]: [node.name] }
                                data_graphs = { ...data_graphs, [prop.vt]: type_init }
                            } else {
                                // grab the already seen set of nodes pertaining to that knowledge graph
                                let kg_nodes = data_graphs[prop.vt]
                                // type exists in graph labeler
                                if (kg_nodes[prop.v]) {
                                    let type_add = kg_nodes[prop.v]
                                    type_add.push(node.name)
                                    kg_nodes = { ...kg_nodes, [prop.v]: type_add }
                                    data_graphs = { ...data_graphs, [prop.vt]: kg_nodes }
                                } else {
                                    // type does not exists
                                    let type_init = { [prop.v]: [node.name] }
                                    data_graphs = { ...data_graphs, [prop.vt]: type_init }
                                }
                            }
                        }
                    })
                }
            }
        });

        Object.keys(data_graphs).forEach(key => {
            let parent = RED.nodes.workspace(key)
            if (parent) {
                _labels[parent.label] = {}
                if (data_graphs[key]) {
                    Object.keys(data_graphs[key]).forEach(node_key => {
                        let node = RED.nodes.node(node_key)
                        _labels[parent.label][node.name] = data_graphs[key][node_key]
                    })

                }
            }
        })
        return _labels
    }

    async function loadNodes() {
        activeWorkspace = RED.workspaces.active();
        if (activeWorkspace !== 0) {
            treatments = []
            outcomes = []
            const nodesPromise = new Promise((resolve, reject) => {
                parentNode = RED.nodes.workspace(activeWorkspace) || RED.nodes.subflow(activeWorkspace) || RED.nodes.submodel(activeWorkspace);
                nodes = RED.nodes.groups(activeWorkspace)
                nodes = nodes.concat(RED.nodes.filterNodes({ z: activeWorkspace }))
                nodes.unshift(parentNode)
                nodes = RED.nodes.createExportableNodeSet(nodes)

                nodes.forEach(node => {
                    if (node.type !== "tab") {
                        nn = { ...nn, [node.name]: node.id }
                        inv_nn = { ...inv_nn, [node.id]: node.name }
                        if (node.treatment) {
                            treatments.push(node.id)
                            node.wires[0].forEach(descendant => {
                                treatment_descendants.push(descendant)
                            })
                        }
                        else if (node.outcome) {
                            outcomes.push(node.id)
                        } else {
                            observed.push(node.id)
                        }
                    }
                })
                resolve("finished")
            })
            nodesPromise.then(value => {
                let treatment_text = ""
                treatments.forEach(trtment => {
                    treatment_text += inv_nn[trtment] + "|"
                })
                treatment_text = treatment_text.substring(0, treatment_text.length - 1)
                $("#treatment").val(treatment_text)
                $("#ca-treatment").val(treatment_text)


                let outcome_text = ""
                outcomes.forEach(outcome => {
                    outcome_text += inv_nn[outcome] + "|"
                })
                outcome_text = outcome_text.substring(0, outcome_text.length - 1)
                $("#outcome").val(outcome_text)
                $("#ca-outcome").val(outcome_text)


                fetchModelAnalysis()
                setAdjusters()
            })
            return nodesPromise
        }
        console.log("@[loadNodes] Finished loading workspace nodes and returning ")
        return
    }

    async function createParentChildIndex() {
        parent_child = {}
        if (nodes !== null) {
            nodes.forEach(node => {
                if (node.type !== "tab") {
                    if (node.wires) {
                        let children = node.wires[0]
                        for (indx in children) {
                            let child = children[indx]
                            if (parent_child[child]) {
                                let prev_list = parent_child[child]
                                prev_list.push(node.id)
                                parent_child = { ...parent_child, [child]: prev_list }
                            } else {
                                parent_child = { ...parent_child, [child]: [node.id] }
                            }
                        }
                    }
                }
            })
        }
        return parent_child
    }

    function d_separation(path_info) {
        let { path, set, path_type, path_index } = path_info
        set = new Set(set)
        let is_blocked = false
        let blocked_by_collider = false
        let conditioned_on_descendant = false
        let collider = ""
        let collider_descendants = []
        path = path.map(node_name => {
            return nn[node_name]
        })
        path.forEach((node_id, l) => {
            if (l >= 1 && l < path.length - 1) {
                previous = path[l - 1]
                current = path[l]
                next = path[l + 1]
                // check if subpath is a collider if not then it is a chain or fork
                let middle_parents = new Set(parent_child[current])
                if (middle_parents.has(previous) && middle_parents.has(next)) {
                    // IF CONDITIONING SET DOES NOT CONTAIN COLLIDER THEN IT IS BLOCKED
                    if (set.has(current) && set.size === 1) {
                        blocked_by_collider = false
                    } else {
                        blocked_by_collider = true
                        collider_detected = true
                        collider = current
                        addCollider(path_info, collider)
                    }
                    // CHECK FOR POSSIBLE CONDITIONING ON DESCENDANTS OF COLLIDER 
                    // convert node first to get wires of node which represent links to descendants
                    let collider_node = RED.nodes.convertNode(RED.nodes.node(current))
                    let adj_desc = collider_node.wires[0].map(wire => {
                        if (set.has(wire)) {
                            collider_descendants.push(wireƒ)
                        }
                        return set.has(wire)
                    })
                    adj_desc = new Set(adj_desc)
                    conditioned_on_descendant = adj_desc.has(true)
                }
            }
        })
        let blocked_by_adj = []
        path = new Set(path)
        set.forEach(value => {
            if (path.has(value)) {
                blocked_by_adj.push(value)
                is_blocked = true
            }
        })
        if (blocked_by_collider && !conditioned_on_descendant) {
            is_blocked = true
        } else if (blocked_by_collider && conditioned_on_descendant) {
            is_blocked = false
        }
        return [is_blocked, collider]
    }

    function updateSelectedPaths(path_index) {
        let currentPaths = [...selected_paths]
        let temp = []
        let notFound = true
        let popped = ""
        while (notFound) {
            popped = currentPaths.pop()
            notFound = popped === path_index ? false : true
            if (notFound) {
                temp.push(popped)
            }
        }
        while (temp.length > 0) {
            popped = temp.pop()
            currentPaths.push(popped)
        }
        selected_paths = [...currentPaths]
    }

    function selectPath(event, path, path_index, type, adjust) {
        if (adjust) {
            path_index = "" + path_index
        }
        let current_wires = type === "bd" ? backdoor_wires : frontdoor_wires
        let selectedSet = new Set(selected_paths)
        if (selectedSet.has(path_index)) {
            // update selected paths array
            updateSelectedPaths(path_index)
            selectedSet = new Set(selected_paths)

            path.forEach((n_id, index) => {
                if (path[index + 1]) {
                    // check if next node is child or parent
                    let current = nn[n_id]
                    let next = nn[path[index + 1]]
                    // get parents
                    let parents = parent_child[current]
                    parents = new Set(parents)
                    // get children
                    let children = RED.nodes.convertNode(RED.nodes.node(current))
                    let child_set = new Set(children.wires[0])
                    let type = open_paths.has(path_index) && selectedSet.has(path_index) ? true : false
                    if (adjust) {
                        let temp = new Set(changed_paths)
                        console.log("adjusted and path changed: ", temp.has(path_index))
                        if (temp.has(path_index)) {
                            type = !type
                        }
                    }
                    if (parents.has(next)) {
                        if (current_wires[[next, current]]) {
                            // get selectedBySet
                            let selectedBy = current_wires[[next, current]]["selectedBy"]
                            selectedBy.delete(path_index)
                            if (selectedBy.size > 0) {
                                selectedBy.forEach(path => {
                                    if (open_paths.has(path)) {
                                        type = true
                                    }
                                })
                                current_wires = {
                                    ...current_wires, [[next, current]]: { "type": type, "selectedBy": selectedBy }
                                }
                            } else {
                                // delete current edge from current wires
                                delete current_wires[[next, current]]
                            }

                        }
                    } else if (child_set.has(next)) {

                        if (current_wires[[current, next]]) {
                            // get selectedBySet
                            let selectedBy = current_wires[[current, next]]["selectedBy"]
                            selectedBy.delete(path_index)
                            if (selectedBy.size > 0) {
                                selectedBy.forEach(path => {
                                    if (open_paths.has(path)) {
                                        type = true
                                    }
                                })
                                current_wires = {
                                    ...current_wires, [[current, next]]: { "type": type, "selectedBy": selectedBy }
                                }
                            } else {
                                // delete current edge from current wires
                                delete current_wires[[current, next]]
                            }

                        }
                    }
                }
            })
        }
        else {
            selected_paths.push(path_index)
            selectedSet = new Set(selected_paths)
            path.forEach((n_id, index) => {
                if (path[index + 1]) {
                    // check if next node is child or parent
                    let current = nn[n_id]
                    let next = nn[path[index + 1]]
                    // get parents
                    let parents = parent_child[current]
                    parents = new Set(parents)
                    // get children
                    let children = RED.nodes.convertNode(RED.nodes.node(current))
                    let child_set = new Set(children.wires[0])
                    let type = open_paths.has(path_index) && selectedSet.has(path_index) ? true : false

                    if (adjust) {
                        type = open_paths.has(parseInt(path_index)) && selectedSet.has(path_index) ? true : false
                    }
                    if (adjust) {
                        let temp = new Set(changed_paths)
                        console.log(temp)
                        console.log(path_index)
                        console.log("adjusted and path changed: ", temp.has(parseInt(path_index)))
                        if (temp.has(parseInt(path_index))) {
                            type = !type
                        }
                    }
                    if (parents.has(next)) {
                        if (current_wires[[next, current]]) {
                            // get selectedBySet
                            let selectedBy = current_wires[[next, current]]["selectedBy"]
                            selectedBy.add(path_index)
                            current_wires = {
                                ...current_wires, [[next, current]]: { "type": type, "selectedBy": selectedBy }
                            }
                        } else {
                            // initialize currently selectedBySet
                            current_wires = {
                                ...current_wires, [[next, current]]: { "type": type, "selectedBy": new Set([path_index]) }
                            }
                        }

                    } else if (child_set.has(next)) {

                        if (current_wires[[current, next]]) {
                            // get selectedBySet
                            let selectedBy = current_wires[[current, next]]["selectedBy"]
                            selectedBy.add(path_index)
                            current_wires = {
                                ...current_wires, [[current, next]]: { "type": type, "selectedBy": selectedBy }
                            }
                        } else {
                            // initialize currently selectedBySet
                            current_wires = {
                                ...current_wires, [[current, next]]: { "type": type, "selectedBy": new Set([path_index]) }
                            }
                        }
                    }


                }
                if (colliders[n_id]) {
                    if (type === "bd") {
                        let backset = new Set(colliders[n_id].back)
                        if (backset.has(parseInt(path_index))) {
                            RED.view.select(n_id)
                        }
                    }
                }
                if (adjusters.has(n_id)) {
                    RED.view.select(n_id)
                }
            })
        }
        if (type === "bd") {
            backdoor_wires = { ...current_wires }
        }
        if (type === "fd") {
            frontdoor_wires = { ...current_wires }
        }
        RED.view.redraw()
    }

    /**
    * @name addPath
    * @description Adds a backdoor and frontdoor to their respective containers 
    * @param { Object } container Object containing div information of frontdoor/backdoor container
    * @param { string } path The current path adding to container
    * @param { int } path_index The current path index
    * @param { Array } collider Contains information describing if ita a collider or not
    * @param { string } type Frontdoor = "fd" Backdoor = "bd"
    * */
    // TODO: Get container according to type
    function addPath(container, path, path_index, collider, type) {
        if (open_paths.has(path_index)) {
            // console.log("@addPath path index is set of open paths", path_index, backdoors[0][path_index])
        }
        var div = $("<div>", {
            id: type + "_" + path_index,
            class: "red-ui-path-list-item ",
        }).css({ "width": "100%", "cursor": "pointer" })
        if (type === "bd") {
            collider[0] ? div.addClass("red-ui-backdoor-closed").toggleClass("selected", false) : div.addClass("red-ui-backdoor-open").toggleClass("selected", false)
        }
        if (type === "fd") {
            collider[0] ? div.addClass("red-ui-frontdoor-closed").toggleClass("selected", false) : div.addClass("red-ui-frontdoor-open").toggleClass("selected", false)
        }

        var span = $("<span>").appendTo(div)
        // label
        $("<div>", {
            class: "red-ui-path-item-label",
            style: { "width": "100%" },
            text: path
        }).appendTo(span)
        div.on("click", (event) => {
            event.preventDefault()
            selectPath(event, path, path_index, type, false)
            div.toggleClass("selected")
        })
        if (collider[0]) {
            div.appendTo(container)
        } else {
            div.prependTo(container)
        }
    }
    function addColliders(colliderContainer) {
        Object.keys(colliders).forEach((collider_id, index) => {
            let back = colliders[collider_id].back
            let front = colliders[collider_id].front
            var div = $("<div>", {
                id: "cd_" + collider_id,
                class: "red-ui-path-list-item ",
            }).css({ "width": "100%", "cursor": "pointer" })
            var span = $("<span>").appendTo(div)
            // label
            $("<div>", {
                class: "red-ui-path-item-label",
                style: { "width": "100%" },
                text: inv_nn[collider_id] + " ~ Backdoor closed " + back.length + "; Frontdoors opened: " + front.length
            }).appendTo(span)

            div.on("click", () => {
                RED.view.select(collider_id)
            })
            div.appendTo(colliderContainer)
        })
    }
    // TODO : abstract this function a bit more [comment: thinking we can populate adjuster container somewhere else as well where we are reading from ndoes already]
    function setAdjusters() {
        let adjusters = $("#adjusters")
        let trt_set = new Set(treatments)
        let out_set = new Set(outcomes)
        let counter = 0
        nodes.forEach(node => {
            if (node.type !== "tab") {
                if (!node.treatment && !node.outcome) {
                    let parents = parent_child[node.id]
                    if (parents !== undefined) {
                        if (!trt_set.has(node.id) && !out_set.has(node.id)) {
                            counter += 1
                            adjusters.append("<option value=" + node.id + ">" + node.name + "</option>")
                        }
                    } else {
                        counter += 1
                        adjusters.append("<option value=" + node.id + ">" + node.name + "</option>")
                    }
                }
            }
        })
        adjusters.attr("size", 10)
    }

    // populate UI with model analysis
    function fetchModelAnalysis() {
        createParentChildIndex()
        loadLabels()
        let trt_names = []
        let out_names = []
        treatments.forEach((trt, i) => {
            trt_names.push(inv_nn[trt])
        })
        outcomes.forEach((out, i) => {
            out_names.push(inv_nn[out])
        })
        fetch("http://127.0.0.1:5000/backdoors/" + model_name + "/" + trt_names + "/" + out_names)
            .then(res => res.json())
            .then(json => {
                backdoors = [...json["backdoors"]]
                frontdoors = [...json["frontdoors"]]
                colliders = {}
                open_paths.clear()
                closed_paths.clear()
                let counter = 0
                let backdoorContainer = $("#cm-backdoors")
                let frontdoorContainer = $("#cm-frontdoors")
                let colliderContainer = $("#cm-colliders")

                treatments.forEach((treatment, i) => {
                    outcomes.forEach((outcome, j) => {
                        if (backdoors.length > 1) {
                            console.log(backdoors[i][j])
                        } else {
                            if (backdoors[i].length > 0) {
                                // update backdoors header

                                let blocked_doors = 0
                                backdoors[i].forEach((path, path_index) => {
                                    let response = d_separation({ "path": path, "set": [], "path_type": "back", "path_index": path_index })
                                    let collider_detected = response[0]
                                    let collider_id = response[1]
                                    counter += 1
                                    if (collider_detected) {
                                        blocked_doors += 1
                                        closed_paths.add(path_index)
                                    }
                                    else {
                                        open_paths.add(path_index)
                                    }
                                    // add item to container w/out collider
                                    addPath(backdoorContainer, path, path_index, response, "bd")
                                }, i, j)
                                let open_doors = counter - blocked_doors
                                let new_text = "Backdoors [ Closed: " + blocked_doors + " Open: " + open_doors + " ]"
                                $("#backdoors-title").text(new_text)
                            };


                        };
                        if (frontdoors.length > 1) {
                        } else {
                            if (frontdoors[i].length > 0) {
                                frontdoors[i].forEach((path, path_index) => {
                                    let response = d_separation({ "path": path, "set": [], "path_type": "front", "path_index": path_index })
                                    counter += 1
                                    addPath(frontdoorContainer, path, path_index, response, "fd")
                                }, i, j)

                            }
                        }
                        addColliders(colliderContainer)

                    }, (treatment, i));
                });
            })
            .catch(err => {
                console.log(err)
                RED.notify("[CAUSEWAY] Error:", error, "error")
            })
            .finally(resp => {
                // RED.notify("[CAUSEWAY] Model analysis complete ", "success")
                return backdoors, frontdoors
            });

    }

    function adjusterAnalysis() {
        adjusters = new Set($("#adjusters").val())
        let path_state = {}
        open_paths.forEach(path => {
            path_state = { ...path_state, [path]: true }
        })
        closed_paths.forEach(path => {
            path_state = { ...path_state, [path]: false }
        })

        // clear previous analysis
        adjuster_collider_ids.clear()
        adjuster_open_paths.clear()
        adjuster_closed_paths.clear()

        //  switch state of collider paths
        Object.keys(colliders).map(id => {
            if (adjusters.has(id)) {
                colliders[id].back.forEach(
                    path_id => {
                        path_state = { ...path_state, [path_id]: !path_state[path_id] }
                    }
                )
            }
        })

        // check only original_paths 
        let temp_path_set = []
        open_paths.forEach(path => {
            temp_path_set = new Set(backdoors[0][path])
            let changed = false
            adjusters.forEach(adjuster => {
                if (temp_path_set.has(inv_nn[adjuster]) && !changed) {
                    changed = true
                    path_state = { ...path_state, [path]: !path_state[path] }
                }
            })
        })

        changed_paths = []
        unchanged_paths = []
        let temp_paths = new Set(open_paths)
        Object.keys(path_state).forEach(path_index => {
            path_index = parseInt(path_index)
            // if was open path but now closed then add to changed paths
            if (temp_paths.has(path_index) && !path_state[path_index]) {
                changed_paths.push(path_index)
            }
            if (temp_paths.has(path_index) && path_state[path_index]) {
                unchanged_paths.push(path_index)
            }
        })

        let adj_text = ""
        adjusters.forEach(adj => {
            adj_text += inv_nn[adj] + " "
        })
        let total_paths = closed_paths.size + changed_paths.length
        $("<div />", {
            id: "analysis-console-total",
            text: "Total paths closed " + total_paths + "/" + backdoors[0].length
        }).appendTo($("#analysis-console"))
        $("<div />", {
            id: "analysis-console-adjusted",
            text: "Selected adjusters [ " + adj_text + " ] closed " + changed_paths.length + "/" + open_paths.size + " open backdoor paths"
        }).appendTo($("#analysis-console"))


        changed_paths.forEach(path_index => {
            // clone old div and add new id
            let div_id = "bd_" + path_index + "_a"
            var changed_path = $("<div>", {
                id: div_id,
                class: "red-ui-path-list-item red-ui-backdoor-closed selected",
                text: backdoors[0][path_index]
            }).css({ "width": "100%", "cursor": "pointer" })
            changed_path.toggleClass("selected")
            changed_path.appendTo($("#analysis-console"))

            changed_path.on("click", (event) => {
                event.preventDefault()
                let path = backdoors[0][path_index]
                selectPath(event, path, path_index, "bd", true)
                changed_path.toggleClass("selected")
            })
        })
        unchanged_paths.forEach(path_index => {
            let div_id = "bd_" + path_index + "_a"

            let unchanged_path = $("<div>", {
                id: div_id,
                class: "red-ui-path-list-item red-ui-backdoor-open selected",
                text: backdoors[0][path_index]
            }).css({ "width": "100%", "cursor": "pointer" })

            unchanged_path.toggleClass("selected", false)
            unchanged_path.appendTo($("#analysis-console"))
            unchanged_path.on("click", (event) => {
                event.preventDefault()
                let path = backdoors[0][path_index]
                selectPath(event, path, path_index, "bd", true)
                unchanged_path.toggleClass("selected")

            })
        })

    }


